{"candidate_predicates": [
  {
    "name": "IS_PLAN",
    "definition": "The reasoning explicitly expresses an intended future action or ordered sequence of future actions that the agent intends to carry out.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text expressing the intended future action or sequence of actions."
      }
    ],
    "assertion_conditions": [
      "The reasoning explicitly identifies at least one action the agent intends to perform next, rather than one already performed."
    ],
    "exclusion_conditions": [
      "The reasoning only reports completed actions or states a conclusion without expressing a future intention.",
      "The reasoning only speculates about a hypothesis without committing to an action to take."
    ]
  },
  {
    "name": "IDENTIFIES_CAUSE_OF_FAILURE",
    "definition": "The reasoning explains why a prior attempt or its observed result was wrong or unsuccessful, attributing the failure to a specific identifiable cause rather than merely noting that a failure occurred.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text that diagnoses the cause of an observed failure or erroneous result."
      }
    ],
    "assertion_conditions": [
      "The reasoning refers to a prior unsuccessful attempt or to an observed erroneous/empty result.",
      "The reasoning states a specific cause explaining that outcome, such as a mismatched identifier, a wrong assumption about data values, or an incorrect scope."
    ],
    "exclusion_conditions": [
      "The reasoning merely reports that an operation errored without attributing any cause.",
      "The reasoning speculates about failure modes of an attempt that has not yet occurred."
    ]
  },
  {
    "name": "RECTIFIES_FAILED_ATTEMPT",
    "definition": "The action modifies a previously failing artifact, query, or procedure in a way directed at the cause of the failure reported by the observation, with the aim of producing a correct result, rather than repeating the same attempt unchanged.",
    "parameters": [
      {
        "name": "corrective_action",
        "type": "action",
        "description": "The action that rewrites, adjusts, or otherwise changes the previously failing artifact or procedure."
      },
      {
        "name": "failure_observation",
        "type": "observation",
        "description": "The observation reporting the error, empty result, or other failure of the earlier attempt."
      }
    ],
    "assertion_conditions": [
      "The observation reports a failure, error, or unusable result of an earlier attempt.",
      "The action changes the same artifact or procedure that produced that failure, and the change corresponds to the cause of the failure rather than being an unchanged retry."
    ],
    "exclusion_conditions": [
      "The action simply re-executes the identical, unmodified attempt.",
      "The action concerns an artifact or procedure unrelated to the observed failure.",
      "The observation does not report a failure or unusable result."
    ]
  },
  {
    "name": "TESTS_ASSUMPTION_WITH_PROBE",
    "definition": "A targeted action empirically tests a specific uncertainty or assumption raised in reasoning, and the resulting observation supplies interpretable evidence that resolves or quantifies that uncertainty.",
    "parameters": [
      {
        "name": "probe_action",
        "type": "action",
        "description": "The action that performs the targeted check or probe."
      },
      {
        "name": "assumption_reasoning",
        "type": "reasoning",
        "description": "The reasoning identifying the specific assumption or uncertainty being tested."
      },
      {
        "name": "probe_result",
        "type": "observation",
        "description": "The observation reporting the outcome of the probe that bears on the tested assumption."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies a specific assumption or uncertainty whose truth would change the result.",
      "The action is constructed to elicit the information needed to settle that assumption.",
      "The observation reports a result that can be interpreted as supporting or refuting the assumption."
    ],
    "exclusion_conditions": [
      "The action is unrelated to the stated assumption.",
      "The observation does not address the assumption being tested.",
      "No identifiable assumption or uncertainty motivates the action."
    ]
  },
  {
    "name": "CONFIRMS_RESULT_BY_INDEPENDENT_RECOMPUTATION",
    "definition": "A verification action recomputes an already obtained quantity through a substantively different procedure or data-access path, and the resulting observation agrees with the earlier result, thereby corroborating it.",
    "parameters": [
      {
        "name": "verification_action",
        "type": "action",
        "description": "The action that independently recomputes or re-derives the same quantity by a different route."
      },
      {
        "name": "baseline_observation",
        "type": "observation",
        "description": "The observation reporting the initial computed result that is to be corroborated."
      },
      {
        "name": "corroborating_observation",
        "type": "observation",
        "description": "The observation reporting the independently recomputed result."
      }
    ],
    "assertion_conditions": [
      "The baseline observation reports a value produced by a prior computation.",
      "The verification action recomputes the same quantity using a different library, route, or method than the prior computation.",
      "The corroborating observation reports a value that matches the baseline value for the same quantity."
    ],
    "exclusion_conditions": [
      "The second computation repeats the identical code path and parameters, so agreement adds no independent support.",
      "The recomputed quantity differs from the baseline quantity.",
      "The results disagree, or no comparison between them is available."
    ]
  },
  {
    "name": "MAPS_UNDERSPECIFIED_TERM_TO_CONCRETE_VALUES",
    "definition": "The reasoning resolves a term in the requirement that does not literally match any value in the data by using reference documentation content that enumerates categories or sources, and adopts the corresponding concrete values as the operative criterion.",
    "parameters": [
      {
        "name": "mapping_reasoning",
        "type": "reasoning",
        "description": "The reasoning that maps the underspecified requirement term onto concrete data values."
      },
      {
        "name": "documentation_observation",
        "type": "observation",
        "description": "The observation containing reference or documentation content enumerating categories, sources, or fields."
      }
    ],
    "assertion_conditions": [
      "The requirement uses a term that does not appear as a literal value in the data under consideration.",
      "The observation contains reference or documentation content that groups or enumerates the concrete categories or sources.",
      "The reasoning uses that documentation content to select the concrete values that correspond to the term and adopts them as the selection criterion."
    ],
    "exclusion_conditions": [
      "The reasoning merely restates the requirement term without converting it into concrete values.",
      "The observation reports measurements of the target data rather than reference documentation enumerating categories.",
      "The documentation content does not determine which concrete values correspond to the term."
    ]
  },
  {
    "name": "ASSESSES_INTERPRETATION_AMBIGUITY",
    "definition": "The reasoning explicitly recognizes that a requirement admits more than one plausible reading, enumerates at least two candidate interpretations, and evaluates how they would differ in outcome before settling on one.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text that identifies and weighs competing interpretations of the requirement."
      }
    ],
    "assertion_conditions": [
      "The reasoning states that the requirement or its resulting quantity is ambiguous or admits multiple readings.",
      "The reasoning presents at least two candidate interpretations.",
      "The reasoning characterizes how the candidate interpretations would lead to different results or procedures."
    ],
    "exclusion_conditions": [
      "The reasoning commits to a single reading without acknowledging alternatives.",
      "The reasoning merely expresses general uncertainty or doubt without identifying concrete competing interpretations."
    ]
  },
  {
    "name": "VERIFIES_PRODUCED_ARTIFACT",
    "definition": "After a result has been produced, an inspection action reads the produced artifact and the resulting observation reports its actual content as matching the result the reasoning expected it to contain.",
    "parameters": [
      {
        "name": "inspection_action",
        "type": "action",
        "description": "The action that reads or inspects the previously produced artifact."
      },
      {
        "name": "expectation_reasoning",
        "type": "reasoning",
        "description": "The reasoning stating the expected result or deliverable that the artifact should hold."
      },
      {
        "name": "artifact_observation",
        "type": "observation",
        "description": "The observation reporting the actual content or state of the produced artifact."
      }
    ],
    "assertion_conditions": [
      "The artifact was produced by an earlier action in the trajectory.",
      "The reasoning states an expected value or content for that artifact.",
      "The observation reports the artifact's actual content, and that content matches the expectation."
    ],
    "exclusion_conditions": [
      "The action inspects something that was not produced by earlier actions in the trajectory.",
      "The observation shows the artifact missing, empty, or containing content that contradicts the expectation.",
      "The inspection is only performed without any stated expectation to compare against."
    ]
  },
  {
    "name": "GROUNDS_CONCLUSION_IN_OBSERVATION",
    "definition": "The reasoning draws a conclusion that is supported by identifiable content of a specific observation, using that content as evidence rather than merely restating it.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning expressing the evidence-based conclusion."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation supplying evidence for that conclusion."
      }
    ],
    "assertion_conditions": [
      "The reasoning states a conclusion or decision that goes beyond the raw content of the observation.",
      "Identifiable content of the observation supports that conclusion."
    ],
    "exclusion_conditions": [
      "The reasoning merely repeats the observation without drawing a conclusion.",
      "The observation is unrelated to the conclusion or provides no identifiable support."
    ]
  }
]}

